        // --- TEXTURE ATLAS GENERATION ---
        function createTextureAtlas(textures) {
            // Layout: 4 columns (Side, Top, Bottom, Extra), 6 Rows (Block Types)
            // Block Types Order: 1:Grass, 2:Dirt, 3:Stone, 4:Wood, 5:Leaves, 6:Planks
            const types = ['GRASS', 'DIRT', 'STONE', 'WOOD_LOG', 'LEAVES', 'PLANKS'];
            const faces = ['SIDE', 'TOP', 'BOTTOM']; // We map SIDE to all 4 sides. Top/Bottom specific.
            // Wood needs: Side(Log), Top(Rings), Bottom(Rings). Grass: Side(Dirt+Grass), Top(Grass), Bottom(Dirt).

            const atlasSize = 1024;
            const tileSize = atlasSize / 4; // 256px per tile. High quality.
            const canvas = document.createElement('canvas');
            canvas.width = atlasSize; canvas.height = atlasSize;
            const ctx = canvas.getContext('2d');
            ctx.imageSmoothingEnabled = false; // Keep crisp for pixel-perfect UV mapping in shader? No, we want smooth textures. True.
            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = 'high';

            const uvMap = {}; // { blockId: { faceId: {u,v, w,h} } }
            // FaceIds: 0:+X, 1:-X, 2:+Y, 3:-Y, 4:+Z, 5:-Z
            // UV Layout in Atlas: Row = BlockId, Col = FaceVariant (Side, Top, Bottom)

            types.forEach((typeName, row) => {
                const blockId = row + 1;
                uvMap[blockId] = {};
                const config = PALETTE[typeName];
                // Generate 3 unique canvases for this type
                const canvases = {};
                ['SIDE', 'TOP', 'BOTTOM'].forEach((face, col) => {
                    const c = document.createElement('canvas');
                    c.width = tileSize; c.height = tileSize;
                    const cctx = c.getContext('2d');
                    // Use specific config for Top/Bottom if exists
                    let drawConfig = config;
                    if(face === 'TOP' && PALETTE[typeName + '_TOP']) drawConfig = PALETTE[typeName + '_TOP'];
                    if(face === 'BOTTOM' && PALETTE[typeName + '_BOTTOM']) drawConfig = PALETTE[typeName + '_BOTTOM'];
                    // For Wood Side vs Top
                    if(typeName === 'WOOD_LOG' && face === 'SIDE') drawConfig = PALETTE.WOOD_LOG;
                    if(typeName === 'WOOD_LOG' && face !== 'SIDE') drawConfig = PALETTE.WOOD_TOP;
                    if(typeName === 'GRASS' && face === 'SIDE') drawConfig = PALETTE.GRASS_SIDE;
                    if(typeName === 'GRASS' && face === 'TOP') drawConfig = PALETTE.GRASS_TOP;
                    if(typeName === 'GRASS' && face === 'BOTTOM') drawConfig = PALETTE.DIRT;

                    drawKandinsky(cctx, tileSize, tileSize, drawConfig, (blockId*10+col)*1000);
                    canvases[face] = c;
                    // Draw to Atlas
                    ctx.drawImage(c, col * tileSize, row * tileSize);

                    // Store UV coords (normalized 0-1)
                    const u = (col * tileSize) / atlasSize;
                    const v = 1.0 - ((row + 1) * tileSize) / atlasSize; // V flipped for WebGL
                    const w = tileSize / atlasSize;
                    const h = tileSize / atlasSize;

                    // Assign to 6 faces
                    if(face === 'SIDE') {
                        [0,1,4,5].forEach(f => uvMap[blockId][f] = {u,v,w,h});
                    } else if(face === 'TOP') {
                        uvMap[blockId][2] = {u,v,w,h};
                    } else if(face === 'BOTTOM') {
                        uvMap[blockId][3] = {u,v,w,h};
                    }
                });
            });

            const atlasTex = new THREE.CanvasTexture(canvas);
            atlasTex.magFilter = THREE.NearestFilter; // Crisp voxels
            atlasTex.minFilter = THREE.LinearMipmapLinearFilter;
            atlasTex.generateMipmaps = true;
            atlasTex.colorSpace = THREE.SRGBColorSpace;

            return { texture: atlasTex, uvMap };
        }

        // --- SHADER MATERIAL ---
        const voxelVertexShader = `
            attribute vec3 offset;       // Block Position
            attribute vec4 blockData;    // x: blockId, y: faceId (0-5), z: unused, w: unused
            attribute vec2 uvOffset;     // Atlas UV offset (u, v) for this face
            attribute vec2 uvScale;      // Atlas UV scale (w, h) for this face

            varying vec2 vUv;
            varying vec3 vNormal;
            varying float vBlockId;
            varying float vFaceId;

            uniform mat4 modelViewMatrix;
            uniform mat4 projectionMatrix;
            uniform mat3 normalMatrix;

            void main() {
                vBlockId = blockData.x;
                vFaceId = blockData.y;
                vNormal = normalize(normalMatrix * normal);

                // Instance transformation
                vec3 transformed = position + offset;
                vec4 mvPosition = modelViewMatrix * vec4(transformed, 1.0);
                gl_Position = projectionMatrix * mvPosition;

                // UV Calculation
                // Base UV (0-1 on quad) comes from geometry uv attribute
                vUv = uv * uvScale + uvOffset;
            }
        `;

        const voxelFragmentShader = `
            varying vec2 vUv;
            varying vec3 vNormal;
            varying float vBlockId;
            varying float vFaceId;

            uniform sampler2D atlasMap;
            uniform vec3 lightDir;
            uniform vec3 lightColor;
            uniform vec3 ambientColor;

            void main() {
                vec4 texColor = texture2D(atlasMap, vUv);

                // Alpha test for leaves
                if (vBlockId == 5.0 && texColor.a < 0.5) discard; // BlockId 5 = Leaves

                // Simple Lighting (Lambert)
                float diff = max(0.0, dot(vNormal, lightDir));
                vec3 color = texColor.rgb * (ambientColor + lightColor * diff);

                // Fog
                // gl_FragCoord.z / gl_FragCoord.w is depth
                // We'll do fog in vertex or skip for simplicity? 
                // Scene fog handles it if we output gl_FragDepth? No, standard material handles fog. 
                // Custom shader needs manual fog.
                // Skip fog for now, rely on Three.js Fog? No, custom shader bypasses it.
                // Add simple distance fog:
                // float depth = gl_FragCoord.z / gl_FragCoord.w; // Not linear
                // We'll skip fog for performance/code size, scene background covers horizon.

                gl_FragColor = vec4(color, texColor.a);
            }
        `;

        // --- MAIN GAME CLASS (REWRITTEN) ---
        class VoxelGame {
            constructor() {
                this.W = 64; this.H = 48; this.D = 64;
