            generateWorld() {
                document.getElementById('loading').querySelector('div').textContent = 'Sculpting Terrain...';
                const noise = new SimplexNoise(42);
                const {W,H,D,world,idx,blockTypes} = this;
                const hMap = new Float32Array(W*D);

