                    const h = hMap[z*W+x];
                    for(let y=0;y<=h;y++){
                        if(y===h) world[idx(x,y,z)] = blockTypes.GRASS;
                        else if(y>h-4) world[idx(x,y,z)] = blockTypes.DIRT;
